import { Money, TaxShell, yearFrom } from "@/features/tax/TaxShell"; import { requireTenantContext } from "@/lib/auth/tenant"; import { requireTaxCapability } from "@/lib/tax/permissions"; import { getTaxCenterData } from "@/lib/tax/service";
export default async function TaxVendorsPage({ searchParams }: { searchParams: Promise<{ year?: string }> }) { const tenant = await requireTenantContext(); requireTaxCapability(tenant.role, "tax.view"); const year = yearFrom((await searchParams).year); const data = await getTaxCenterData(tenant.companyId, year); return <TaxShell active="/tax/vendors" title="Vendor Reporting" description="Yearly approved spending and record-completeness summaries. Tax-form generation is excluded." year={year}><section className="glass-card overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead className="border-b border-white/10 text-slate-400"><tr>{["Vendor", "Total spent", "Transactions", "Missing receipts", "Categories"].map((x) => <th className="p-4" key={x}>{x}</th>)}</tr></thead><tbody>{data.vendors.map((x) => <tr className="border-b border-white/10" key={x.id}><td className="p-4 font-semibold">{x.name}</td><td className="p-4"><Money cents={x.totalCents} /></td><td className="p-4">{x.transactionCount}</td><td className={`p-4 ${x.missingReceipts ? "text-amber-300" : ""}`}>{x.missingReceipts}</td><td className="p-4 text-slate-300">{x.categories || "—"}</td></tr>)}</tbody></table>{!data.vendors.length && <p className="p-8 text-center text-slate-400">No approved vendor spending for {year}.</p>}</section></TaxShell>; }
